def dr(a, b):
    q, r = divmod(a, b)
    return Q(r"Выполните деление с остатком: $%d:%d$." % (a, b), r"$%d$ (ост. $%d$)" % (q, r), [
     (r"$%d$ (ост. $%d$)" % (q - 1, r + b), r"Ученик взял неполное частное на $1$ меньше: остаток $%d$ больше делителя $%d$." % (r + b, b)),
     (r"$%d$ (ост. $%d$)" % (q + 1, r), r"Ученик ошибся в неполном частном: $%d\cdot%d=%d>%d$." % (b, q + 1, b * (q + 1), a)),
     (r"$%d$ (ост. $%d$)" % (q, r + 1), r"Ученик ошибся при вычитании: $%d-%d\cdot%d=%d$." % (a, b, q, r))])
T("G5_TB_14_599", B3, [dr(978, 13), dr(4295, 126)])
