SY = r"Прямая $a$ задана уравнением $x+2y=5$. Сколько решений имеет система из уравнения прямой $a$ и уравнения $%s$?"
def sy(e, k):
    o = ["единственное решение", "нет решений", "бесконечно много решений"]
    w = {"единственное решение": r"Ученик не сравнил коэффициенты: у прямых разные угловые коэффициенты, они пересекаются.",
         "нет решений": r"Ученик не сравнил коэффициенты: прямые параллельны (коэффициенты пропорциональны, свободные члены — нет).",
         "бесконечно много решений": r"Ученик не сравнил коэффициенты: уравнения равносильны, прямые совпадают."}
    d = [(x, "Ученик ошибся: " + w[k].split(": ", 1)[1]) for x in o if x != k] + [("два решения", r"Ученик забыл, что две различные прямые пересекаются не более чем в одной точке.")]
    return Q(SY % e, k, d)
