C0 = r"Составьте уравнение окружности, симметричной окружности $(x-2)^{2}+(y+3)^{2}=9$ относительно %s."
EQ = {"ox": r"$(x-2)^{2}+(y-3)^{2}=9$", "oy": r"$(x+2)^{2}+(y+3)^{2}=9$", "o": r"$(x+2)^{2}+(y-3)^{2}=9$", "s": r"$(x-2)^{2}+(y+3)^{2}=9$"}
WQ = {"ox": r"Ученик выполнил симметрию относительно оси абсцисс: у центра меняется знак ординаты.", "oy": r"Ученик выполнил симметрию относительно оси ординат: у центра меняется знак абсциссы.", "o": r"Ученик выполнил симметрию относительно начала координат: у центра меняются знаки обеих координат.", "s": r"Ученик записал уравнение исходной окружности; при симметрии меняется положение центра."}
def circ(k, name):
    return Q(C0 % name, EQ[k], [(EQ[x], WQ[x]) for x in ("ox", "oy", "o", "s") if x != k])
T("G9_TB_20_377", QS, [circ("ox", "оси абсцисс"), circ("o", "начала координат")])
